"""Автономная презентация: CMU, KaTeX, аналитические интерактивные 3D-сцены."""
from pathlib import Path
import html
import json
import sys
ROOT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT.parent/'presentation_assets'))
from upgrade_presentations import font_css,MATH_TOOLS

SLIDES=[]
def eq(tex):return '<div class="equation math-tex" data-tex="'+html.escape(tex,quote=True)+'"></div>'
def slide(title,body,tex=None,question=None,answer=None,minutes=2):
    # На лабораторных слайдах держим сцену и её численный результат рядом.
    import re
    body=re.sub(r'(<div class="stage"><canvas[^>]+></canvas></div>)(<div id="(?:orientation-matrix|robot-pose|power-values|velocity-values)" class="equation"></div>)',r'<div class="lab-grid">\1\2</div>',body)
    if tex:body+=''.join(eq(t) for t in ([tex] if isinstance(tex,str) else tex))
    if question:body+='<aside class="discussion"><strong>Обсудим.</strong> '+question+'<details><summary>Показать разбор</summary><p>'+answer+'</p></details></aside>'
    SLIDES.append((title,body,minutes))
def slider(id,title,low,high,value,step=1):
    return f'<label for="{id}">{title}<input id="{id}" type="range" min="{low}" max="{high}" step="{step}" value="{value}"><output></output></label>'
def stage(id,label):return f'<div class="stage"><canvas id="{id}" aria-label="{label}"></canvas></div>'
def controls(body):return '<div class="controls">'+body+'</div>'

slide('Движение тел в пространстве','<p class="eyebrow">Моделирование робототехнических систем · лекция 5</p><h1>Системы координат.<br>Вращения. Винты.</h1><p class="lead">От движения точки к кинематике пространственного робота.</p><p>Нотация ваших лекций · 90 минут · Python и MuJoCo</p>',minutes=1)
slide('Маршрут занятия','<div id="agenda"></div><p>Цель: уметь читать индексы, строить преобразования и объяснять геометрический смысл твиста.</p>')
slide('Одна точка — разные координаты','<p>Физическая точка p не зависит от выбранной системы. Столбец её координат зависит от Ψᵢ.</p><p>Смена координат не означает физическое перемещение точки.</p>',r'p^j=R_i^jp^i+o_i^j',question='Что означает верхний индекс у p?',answer='Систему, в которой выражены координаты точки. Это не номер другой физической точки.')
slide('Нотация исходных лекций','<table><tr><th>Объект</th><th>Соглашение</th></tr><tr><td>Hᵢʲ, Rᵢʲ</td><td>Из Ψᵢ в Ψⱼ</td></tr><tr><td>Tᵢᵏ˒ʲ</td><td>Тело i относительно j, выражено в Ψₖ</td></tr><tr><td>T=(w;v)</td><td>Столбец: угловая часть первой</td></tr><tr><td>W=(τ F)</td><td>Строка: момент, затем сила</td></tr></table><p>H — конфигурация; T — твист. В Modern Robotics буква T означает другой объект.</p>')
slide('Шесть степеней свободы','<p>Свободное твёрдое тело имеет три поступательные и три вращательные степени свободы.</p><p>Условие жёсткости сохраняет расстояния между точками. Рамка Ψᵢ связана с телом.</p>',r'\|p_a-p_b\|=\mathrm{const}')
slide('Матрица поворота из базисных векторов','<p>Столбцы — оси исходной Ψᵢ, выраженные в целевой Ψⱼ. Так легче проверять направление преобразования.</p>',r'R_i^j=\begin{bmatrix}(\hat x_i)^j&(\hat y_i)^j&(\hat z_i)^j\end{bmatrix}')
slide('Почему SO(3)','<p>Ортогональность сохраняет длины и углы. Положительный определитель исключает отражение.</p>',[r'SO(3)=\{R\in\mathbb R^{3\times3}:R^TR=I,\ \det R=1\}',r'R_j^i=(R_i^j)^T'],question='У матрицы девять чисел. Почему не девять степеней свободы?',answer='Элементы связаны ограничениями ортонормированности. Независимых параметров ориентации три.')
slide('Поворот тела или смена координат?','<p>Если Ψ₂ повёрнута на +θ вокруг z₁, её оси в Ψ₁ задаются R₂¹. Координаты из Ψ₁ в Ψ₂ переводит обратная матрица.</p>',[r'R_2^1=\begin{bmatrix}\cos\theta&-\sin\theta&0\\\sin\theta&\cos\theta&0\\0&0&1\end{bmatrix}',r'R_1^2=(R_2^1)^T'],question='Куда перейдёт вектор x₁ при θ=90° в координатах Ψ₂?',answer='В (0,−1,0). Отрицательный знак возникает из направления смены координат.')
slide('Лаборатория ориентации','<p>Изменяйте углы и поворачивайте сцену мышью или пальцем. Это аналитическая 3D-визуализация, не MuJoCo.</p>'+controls(slider('rot-x','α вокруг x, °',-180,180,25)+slider('rot-y','β вокруг y, °',-180,180,30)+slider('rot-z','γ вокруг z, °',-180,180,45))+stage('orientation','Системы координат и ориентация тела')+'<div id="orientation-matrix" class="equation"></div>',r'R_i^0=R_z(\gamma)R_y(\beta)R_x(\alpha)',minutes=3)
slide('Цепное правило','<p>Ближайшая к вектору матрица действует первой. Индексы помогают проверять совместимость систем.</p>',[r'p^k=R_j^kR_i^jp^i',r'\boxed{R_i^k=R_j^kR_i^j}'])
slide('Порядок поворотов имеет значение','<p>Сравните два активных поворота одного вектора в одной фиксированной системе. Изменение порядка меняет результат.</p>'+controls(slider('order-angle','Угол двух поворотов, °',0,180,90))+stage('rotation-order','Некоммутативность поворотов вокруг x и z')+'<p class="legend">Синий: RₓR_z eₓ · оранжевый: R_zRₓ eₓ · серый: исходный eₓ</p><p id="order-status"></p>',question='При 90° какие получаются направления?',answer='RₓR_z eₓ=e_z; R_zRₓ eₓ=e_y.',minutes=3)
slide('Тильда превращает cross в матрицу','<p>Операция тильда — соглашение о матричном представлении векторного произведения.</p>',r'\widetilde a=\begin{bmatrix}0&-a_z&a_y\\a_z&0&-a_x\\-a_y&a_x&0\end{bmatrix},\qquad\widetilde ab=a\times b')
slide('Вывод угловой скорости','<p>Дифференцируем ортогональность, чтобы понять структуру скорости.</p>',[r'RR^T=I\ \Longrightarrow\ \dot RR^T+R\dot R^T=0',r'(\dot RR^T)^T=-\dot RR^T',r'\widetilde w_i^{j,j}=\dot R_i^jR_j^i'],minutes=3)
slide('Два способа выразить одну скорость','<p>Слева — система наблюдения Ψⱼ, справа — система тела Ψᵢ. Это одно относительное движение.</p>',[r'\widetilde w_i^{j,j}=\dot R_i^jR_j^i,\qquad\widetilde w_i^{i,j}=R_j^i\dot R_i^j',r'\dot R_i^j=\widetilde w_i^{j,j}R_i^j=R_i^j\widetilde w_i^{i,j}'])
slide('Углы и угловая скорость','<p>Производные трёх углов Эйлера в общем случае не равны компонентам w. Их связывает конфигурационно зависимая матрица.</p><p>Сингулярность углового описания не означает, что само тело утратило возможность вращаться.</p>',question='Почему здесь работаем с R и w, а не вводим ещё один порядок Euler-углов?',answer='Матрицы и твисты позволяют обсуждать движение без выбора локальной угловой параметризации и её особых точек.')
slide('Экспонента решает ОДУ вращения','<p>Постоянная пространственно выраженная скорость:</p>',[r'\dot R=\widetilde wR\quad\Longrightarrow\quad R(t)=e^{\widetilde wt}R(0)',r'\dot R=R\widetilde w_b\quad\Longrightarrow\quad R(t)=R(0)e^{\widetilde w_bt}'],question='Можно ли при любом w(t) взять exp от интеграла скорости?',answer='Нет. Генераторы в разные моменты могут не коммутировать; нужен упорядоченный по времени процесс интегрирования.')
slide('Формула Родрига','<p>Отделяем единичную ось от угла. Не подставляем ненормированный вектор в формулу для единичной оси.</p>',[r'\|\hat w\|=1,\qquad\phi=\hat w\theta',r'e^{\widetilde{\hat w}\theta}=I+\sin\theta\,\widetilde{\hat w}+(1-\cos\theta)\widetilde{\hat w}^{\,2}'])
slide('Что происходит около нуля и π','<p>В экспоненте около нуля используем предельные значения или ряды. В логарифме поворота есть неоднозначность ветви.</p>',r'\frac{\sin\theta}{\theta}\to1,\qquad\frac{1-\cos\theta}{\theta^2}\to\frac12',question='При нулевом повороте какова ось?',answer='Она не определена однозначно. При θ=π знак оси тоже неоднозначен для данного R.')
slide('Численный шаг и геометрия','<p>Аддитивный Euler обычно выводит матрицу из SO(3). Экспоненциальный шаг сохраняет ортогональность с точностью округления.</p>',[r'R_{n+1}^{E}=R_n+h\widetilde wR_n',r'R_{n+1}^{G}=e^{h\widetilde w}R_n'],question='Сохранить SO(3) — значит получить точное движение?',answer='Только в данном опыте с постоянной скоростью экспоненциальный шаг точен. Для переменной скорости удержание w на шаге обычно даёт первый порядок.')
slide('Лаборатория дрейфа SO(3)','<p>Постоянная w=(0,3;−0,4;1) рад/с, длительность 10 с. На графике десятичный логарифм ошибки ортогональности.</p>'+controls(slider('drift-h','Шаг h, с',.01,.3,.05,.01))+stage('drift','Ошибка ортогональности при Euler и экспоненциальном шаге')+'<p id="drift-status"></p>',minutes=3)
slide('От вращения к полной конфигурации','<p>Вводим перенос начала тела. Последняя координата точки равна 1, свободного вектора — 0.</p>',[r'P^i=\begin{bmatrix}p^i\\1\end{bmatrix},\quad P^j=H_i^jP^i',r'H_i^j=\begin{bmatrix}R_i^j&o_i^j\\0&1\end{bmatrix}\in SE(3)'])
slide('Обращение H: не транспонирование','<p>Сначала отменяем перенос, затем поворот.</p>',r'\boxed{H_j^i=(H_i^j)^{-1}=\begin{bmatrix}(R_i^j)^T&-(R_i^j)^To_i^j\\0&1\end{bmatrix}}',question='Что нарушится, если взять Hᵀ?',answer='Перенос попадёт в нижнюю строку, и матрица перестанет иметь требуемый вид SE(3).')
slide('Композиция конфигураций','<p>Правило индексов то же, что для вращений; переносы складываются после выражения в одной системе.</p>',[r'H_i^k=H_j^kH_i^j',r'o_i^k=R_j^ko_i^j+o_j^k'],question='Почему нельзя просто сложить два исходных вектора переноса?',answer='Они выражены в разных системах координат. Первый перенос нужно предварительно повернуть в целевую систему.')
slide('Одна проверка с числами','<p>Поворот +90° вокруг z; перенос (0,3;−0,2;0,4) м. Исходная точка (0,2;0,1;0) м.</p>',r'\begin{bmatrix}0&-1&0&0.3\\1&0&0&-0.2\\0&0&1&0.4\\0&0&0&1\end{bmatrix}\begin{bmatrix}0.2\\0.1\\0\\1\end{bmatrix}=\begin{bmatrix}0.2\\0\\0.4\\1\end{bmatrix}',question='Что получится для свободного вектора с теми же первыми тремя числами?',answer='При последней координате 0 перенос исчезает: (−0,1;0,2;0;0).')
slide('Твист: производная конфигурации','<p>В матричной форме твист принадлежит алгебре se(3), а не группе SE(3). Последняя строка нулевая.</p>',[r'\widetilde T_i^{j,j}=\dot H_i^jH_j^i,\qquad\widetilde T_i^{i,j}=H_j^i\dot H_i^j',r'\widetilde T=\begin{bmatrix}\widetilde w&v\\0&0\end{bmatrix},\qquad T=\begin{bmatrix}w\\v\end{bmatrix}'])
slide('Линейная часть твиста: важная тонкость','<p>Для пространственного твиста v — поле скорости в начале системы выражения. Оно обычно отличается от скорости начала тела.</p>',[r'v_i^{j,j}=\dot o_i^j-\widetilde w_i^{j,j}o_i^j',r'\boxed{\dot p^j=w_i^{j,j}\times p^j+v_i^{j,j}}',r'v_i^{i,j}=R_j^i\dot o_i^j'],minutes=3)
slide('Твист описывает поле скоростей','<p>Необязательно иметь материальную точку в начале системы выражения. Продолжение поля скоростей туда и определяет v.</p>',r'w=(0,0,\omega),\quad r=(a,0,0)\quad\Rightarrow\quad v=r\times w=(0,-a\omega,0)',question='На оси вращения скорость нулевая. Почему v не ноль?',answer='Начало системы выражения не лежит на оси. В точке оси члены w×r и v взаимно уничтожаются.')
slide('Adjoint: выражаем твист в другой системе','<p>Меняется только система выражения k; тело движения i и тело сравнения j остаются прежними.</p>',[r'T_i^{k,j}=\operatorname{Ad}_{H_j^k}T_i^{j,j}',r'\operatorname{Ad}_{H}=\begin{bmatrix}R&0\\\widetilde oR&R\end{bmatrix}'],question='Почему недостаточно повернуть обе тройки векторов через R?',answer='При смене начала меняется линейная часть поля скорости. Этот эффект даёт нижний левый блок õR.')
slide('Wrench и мощность','<p>Ваша нотация: wrench — строка. Момент определён относительно начала той же системы.</p>',[r'W_i^k=\begin{bmatrix}\tau_i^k&F_i^k\end{bmatrix}',r'\mathcal P=W_i^kT_i^{k,j}=\tau_i^kw_i^{k,j}+F_i^kv_i^{k,j}'])
slide('Вывод преобразования строки сил','<p>Физическая мощность не зависит от системы выражения.</p>',[r'T^k=\operatorname{Ad}_{H_j^k}T^j,\quad W^kT^k=W^jT^j',r'\boxed{W_i^k=W_i^j\operatorname{Ad}_{H_k^j}}'],question='Откуда появляется inverse transpose в других книгах?',answer='Там wrench часто хранится столбцом. Транспонирование нашего строкового равенства даёт привычную двойственную формулу.',minutes=3)
slide('Лаборатория мощности','<p>Меняем положение системы выражения. Компоненты скорости и момента меняются, мощность остаётся той же.</p>'+controls(slider('power-x','Перенос по x, м',-.6,.6,.3,.05)+slider('power-angle','Поворот вокруг z, °',-180,180,45))+stage('power','Две системы выражения твиста и силы')+'<div id="power-values" class="equation"></div><p id="power-status"></p>',minutes=3)
slide('Винтовая ось движения','<p>При ненулевом w мгновенное движение раскладывается на вращение вокруг оси и перенос вдоль неё.</p>',[r'v=r\times w+\lambda w',r'\lambda=\frac{w^Tv}{\|w\|^2},\qquad r=\frac{w\times v}{\|w\|^2}'],question='Что делать при w=0?',answer='Это чистый перенос. Формулы с делением на ||w||² к нему не применимы.')
slide('Экспонента SE(3)','<p>Постоянный пространственный твист интегрируется слева. Для связанного постоянного твиста экспонента стояла бы справа.</p>',[r'\dot H=\widetilde TH\quad\Rightarrow\quad H(t)=e^{\widetilde Tt}H(0)',r'e^{\widetilde{\hat T}q}=\begin{bmatrix}R(q)&V(q)v\\0&1\end{bmatrix}'])
slide('Перенос в экспоненте тоже связан с вращением','<p>Единичная угловая ось; q — угол. Перенос обычно не равен vq.</p>',r'\begin{aligned}V(q)&=qI+(1-\cos q)\widetilde{\hat w}\\&\quad +(q-\sin q)\widetilde{\hat w}^{\,2}.\end{aligned}',question='Когда o=vq без поправок?',answer='При чистом поступательном движении. Также при v, параллельном оси вращения, поперечные члены обращаются в ноль.')
slide('Лаборатория винтового движения','<p>Ось параллельна z, смещена по x. Начальная точка на расстоянии 0,3 м от оси. Сцена вращается мышью.</p>'+controls(slider('screw-q','Угол, °',0,720,270,'any')+slider('screw-pitch','Шаг λ, м/рад',-.12,.12,.08,.01)+slider('screw-offset','Смещение оси, м',0,.4,.25,.05)+'<button id="screw-play">▶ / Ⅱ</button>')+stage('screw','Винтовая ось и спираль точки')+'<p id="screw-status"></p>',minutes=3)
slide('От тела к пространственному 3R','<p>В home-позе: оси z₀,x₀,x₀. Стойка вдоль z; следующие звенья вдоль +y. После движения первой оси следующие вращаются вместе с ней.</p>',[r'r_1=(0,0,0)^T,\quad r_2=(0,0,\ell_1)^T',r'r_3=(0,\ell_2,\ell_1)^T,\quad o_4^0(0)=(0,\ell_2+\ell_3,\ell_1)^T'])
slide('Начальные оси суставов','<p>Для вращения линейная часть оси r×ŵ. Aᵢ — сокращение начальной оси из вашей нотации.</p>',[r'A_i:=\hat T_i^{0,i-1}\big|_{q=0}',r'A_1=\begin{bmatrix}0\\0\\1\\0\\0\\0\end{bmatrix},\quad A_2=\begin{bmatrix}1\\0\\0\\0\\\ell_1\\0\end{bmatrix},\quad A_3=\begin{bmatrix}1\\0\\0\\0\\\ell_1\\-\ell_2\end{bmatrix}'])
slide('Product of Exponentials','<p>Три постоянные home-оси, три перемещения и home-конфигурация инструмента.</p>',r'\begin{aligned}H_4^0(q)&=e^{\widetilde A_1q_1}e^{\widetilde A_2q_2}e^{\widetilde A_3q_3}H_4^0(0).\end{aligned}',question='Можно ли отбросить H₄⁰(0)?',answer='Нет. Тогда вы получите преобразование home-конфигурации, но не саму позу инструмента с его начальным смещением.')
slide('Лаборатория пространственного робота','<p>Меняйте три угла или включите кинематическое проигрывание. Цвета звеньев и системы инструмента помогают читать композицию.</p>'+controls(slider('robot-q1','q₁, °',-150,150,25)+slider('robot-q2','q₂, °',-100,100,30)+slider('robot-q3','q₃, °',-130,130,-40)+'<button id="robot-play">▶ / Ⅱ</button>')+stage('robot3r','Пространственный 3R с системами координат')+'<div id="robot-pose" class="equation"></div>',minutes=3)
slide('Дифференциальная кинематика','<p>Предыдущие суставы переносят каждую следующую винтовую ось в её текущую конфигурацию.</p>',[r'T_4^{0,0}=J_s(q)\dot q',r'J_s=\begin{bmatrix}A_1&\operatorname{Ad}_{E_1}A_2&\operatorname{Ad}_{E_1E_2}A_3\end{bmatrix}',r'E_i=e^{\widetilde A_iq_i}'])
slide('Связанный якобиан','<p>Тот же относительный твист выражаем в системе инструмента. Размерность обоих якобианов — 6×3.</p>',[r'T_4^{4,0}=J_b(q)\dot q',r'J_b=\operatorname{Ad}_{H_0^4}J_s'],question='Можно ли тремя приводами независимо задать шесть скоростей позы?',answer='В общем случае нет. Доступные твисты образуют не более чем трёхмерное подпространство.')
slide('Скорость tip: не нижние строки Js','<p>Для начала Ψ₄ восстанавливаем скорость точки из поля твиста.</p>',[r'\dot o_4^0=\widetilde wo_4^0+v',r'J_p=\begin{bmatrix}-\widetilde{o_4^0}&I\end{bmatrix}J_s'],question='Что даёт дифференцирование только позиции из FK?',answer='Трёхмерный якобиан скорости точки Jp. Это не нижние строки пространственного Js и не шестимерный аналитический якобиан углов Эйлера.')
