def main():
    destination=ROOT/'presentation'
    css=(destination/'deck.css').read_text()
    js=(destination/'deck.js').read_text()
    minutes=[s[2] for s in SLIDES]
    # Введение и источники по минуте; распределяем оставшееся время.
    while sum(minutes)>90:
        candidates=[i for i in range(1,len(minutes)-1) if minutes[i]>1]
        index=max(candidates,key=lambda i:(minutes[i],i))
        minutes[index]-=1
    while sum(minutes)<90:
        index=next(i for i in range(1,len(minutes)-1) if minutes[i]<3)
        minutes[index]+=1
    sections=''.join(f'<section class="slide" data-title="{html.escape(title,quote=True)}" data-minutes="{minutes[i]}" aria-label="{i+1}. {html.escape(title,quote=True)}"><h2>{html.escape(title)}</h2>{body}</section>' for i,(title,body,_) in enumerate(SLIDES))
    runtime=(ROOT.parent/'presentation_assets/katex-0.16.22/dist/katex.min.js').read_text()
    document=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Лекция 5 · Пространственная кинематика</title><style>{font_css()}\n{css}</style></head><body><header><strong>Пространственная кинематика</strong><small>Лекция 5 · 90 минут</small><button id="menu">Обзор O</button><button id="fullscreen">Экран F</button></header><main>{sections}</main><footer><button id="previous" aria-label="Предыдущий слайд">←</button><span id="counter"></span><div class="progress"><i id="progress"></i></div><span id="time-label"></span><span class="hint">← → · O обзор · F экран · пробел пауза</span><button id="next" aria-label="Следующий слайд">→</button></footer><dialog id="overview"><button class="close">Закрыть</button><h2>Содержание</h2><div class="items"></div></dialog><dialog id="figure-modal"><button class="close">Закрыть</button><img alt=""></dialog><script id="katex-runtime">{runtime}</script><script>{MATH_TOOLS}</script><script id="deck-code">{js}</script></body></html>'''
    (destination/'index.html').write_text(document)
    plan=['# План презентации: 90 минут','','| Время | Слайд |','|---|---|'];start=0
    for (title,_,_),duration in zip(SLIDES,minutes):
        plan.append(f'| {start}–{start+duration} | {title} |');start+=duration
    (destination/'TEACHING_PLAN.md').write_text('\n'.join(plan)+'\n')
    print(f'{len(SLIDES)} slides, {sum(minutes)} minutes, {len(document.encode())/1e6:.2f} MB')


if __name__=='__main__':main()
